window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-51a8048023eaf74b"]={"versions": [{"id": "FIG-51a8048023eaf74b", "releases": ["R20-11", "R21-11", "R22-11", "R23-11", "R24-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\">\n<li><strong>Klassifikation:</strong> Geometrisches Modell- und Koordinatendefinitionsdiagramm (kinematische Trajektorien- und Straßenparameter-Definition nach ISO 8855 / SAE-Konvention).</li>\n<li><strong>Technischer Zweck:</strong> Definition der Vorzeichenkonventionen und Basismessgrößen für Straßen- und Spurgeometrien zur Standardisierung der anwendungsnahen Schnittstellen (<em>Application Interfaces</em>) im ADAS- und Vehicle Motion Control (VMC)-Subsystem.</li>\n<li><strong>Architektur-Einordnung:</strong></li>\n<li>Dokument: <code>AUTOSAR_CP_EXP_AIADASAndVMC</code> (Explanation of Application Interfaces for ADAS and Vehicle Motion Control).</li>\n<li>Schicht: AUTOSAR Application Layer (SWC-Ebene, Sensor-Fusion, Umfeldmodellierung und Querregelungs-Algorithmen wie LDW, LKA, ALC).</li>\n<li>Das Diagramm harmonisiert die Eingangsgrößen von Sensor-SWCs (Kamera, Lidar, Fusion) für regelnde SWCs (Trajectory Planning, Lateral Control).</li>\n</ul>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><strong>Referenzsysteme & Entitäten:</strong></li>\n<li><strong>Ego-Fahrzeug (Vehicle-fixed Coordinate System):</strong> Ursprung im Fahrzeugreferenzpunkt (typischerweise Mitte Hinterachse oder vordere Stoßstange je nach Sensorik). Längsachse (Dotted Line / x-Achse) weist in Fahrtrichtung.</li>\n<li><strong>Spurmarkierungen & Leitlinien:</strong></li>\n<li><code>Left edge of the lane</code>: Linke Spurberandung.</li>\n<li><code>Centre of the lane</code>: Spurmittellinie (Trajektorien-Sollachse).</li>\n<li><code>Right edge of the lane</code>: Rechte Spurberandung.</li>\n<li><strong>Definierte Schnittstellenvariablen & Datenstrukturen:</strong></li>\n<li><strong>Offset (Lateraler Versatz $y$):</strong></li>\n<li><em>Definition:</em> Abstand zwischen Fahrzeugreferenzlinie und Fahrspurgrenze bzw. Spurmitte entlang der Querachse.</li>\n<li><em>Vorzeichenkonvention:</em> Positiv nach <strong>links</strong> ($+y$), in Übereinstimmung mit dem fahrzeugfesten ISO-8855-Rechtssystem ($x$ = vorwärts, $y$ = links, $z$ = aufwärts).</li>\n<li><strong>Yaw angle (Gierwinkel / Differenzwinkel $\\Delta\\psi$):</strong></li>\n<li><em>Definition:</em> Winkelversatz zwischen der Fahrzeuglängsachse und der Tangente an die Fahrspur.</li>\n<li><em>Vorzeichenkonvention:</em> Positiv gegen den Uhrzeigersinn (mathematisch positiv / Linksdrehung, $+z$-Achse).</li>\n<li><strong>Road curvature (Straßenkrümmung $\\kappa$ bzw. $c_0$):</strong></li>\n<li><em>Definition:</em> Krümmung der Fahrspur ($\\kappa = \\frac{1}{R}$).</li>\n<li><em>Vorzeichenkonvention:</em> Positiv bei Linkskurven ($+$ nach links gekrümmt), negativ bei Rechtskurven. Typischerweise Bestandteil einer Polynombeschreibung (z. B. $y(x) = c_0 + c_1 x + \\frac{c_2}{2} x^2 + \\frac{c_3}{6} x^3$).</li>\n</ul>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ul class=\"fig-list\">\n<li><strong>Berechnungszyklus & Datenfluss:</strong></li>\n<li>Sensor-SWCs (z. B. Frontkamera) ermitteln kontinuierlich im Abtasttakt (z. B. 20 ms–50 ms) die Polynom- oder Spline-Koeffizienten sowie die Relativvariablen (<code>Offset</code>, <code>Yaw angle</code>, <code>Road curvature</code>).</li>\n<li>Übertragung via Sender-Receiver-Kommunikation (<code>VariableDataPrototype</code> über <code>Rte_Read</code> / <code>Rte_Write</code> bzw. Non-blocking Data Semantics) an Umfeldmodell- und Fusions-SWCs.</li>\n<li>Nachgelagerte Regler-SWCs (z. B. Lane Keeping Assist) nutzen die Signale zur Bildung der Soll-Gierrate und des Soll-Lenkmoments für unterlagerte VMC-Aktuatoren (EPS - Electric Power Steering).</li>\n<li><strong>Asynchronität / Validierung:</strong></li>\n<li>Statussignale (Confidence Level, Tracking-Status) sichern die geometrischen Variablen ab; bei Verlust der Sichtbarkeit erfolgt Signal-Degradation oder Fallback auf Odometrie.</li>\n</ul>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li><strong>Vorzeichenkonsistenz (Right-Hand Rule):</strong></li>\n<li>Entwickler von Treiberbausteinen und Sensor-Interfaces müssen sicherstellen, dass Rohdaten proprietärer Sensoren (z. B. Kamerasysteme, die nach rechts positive Vorzeichen liefern) am SWC-Eingangsport exakt auf die AUTOSAR-Vorgabe (links = positiv für Offset, Gierwinkel und Krümmung) invertiert werden.</li>\n<li><strong>Datentypen & Skalierung:</strong></li>\n<li>Verwendung AUTOSAR-konformer <code>ApplicationDataType</code> / <code>ImplementationDataType</code> (z. B. <code>float32</code> oder Festkomma mit <code>CompuMethod</code> für physikalische Einheiten: $\\text{m}$ für Offset, $\\text{rad}$ für Yaw angle, $\\text{1/m}$ für Curvature).</li>\n<li><strong>RTE-Integration:</strong></li>\n<li>Schnittstellenkompatibilität erfordert identische Semantik an P-Port und R-Port (<code>SenderReceiverInterface</code>); Vorzeichenfehler führen unmittelbar zu instabilen Regelkreisen (Mitkopplung statt Gegenkopplung in Querregelalgorithmen).</li>\n</ul>"}, {"id": "FIG-f603d60f8a769973", "releases": ["R25-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\">\n<li><strong>Klassifikation:</strong> Geometrisches Modell- und Koordinatendefinitionsdiagramm (kinematische Trajektorien- und Straßenparameter-Definition nach ISO 8855 / SAE-Konvention).</li>\n<li><strong>Technischer Zweck:</strong> Definition der Vorzeichenkonventionen und Basismessgrößen für Straßen- und Spurgeometrien zur Standardisierung der anwendungsnahen Schnittstellen (<em>Application Interfaces</em>) im ADAS- und Vehicle Motion Control (VMC)-Subsystem.</li>\n<li><strong>Architektur-Einordnung:</strong></li>\n<li>Dokument: <code>AUTOSAR_CP_EXP_AIADASAndVMC</code> (Explanation of Application Interfaces for ADAS and Vehicle Motion Control).</li>\n<li>Schicht: AUTOSAR Application Layer (SWC-Ebene, Sensor-Fusion, Umfeldmodellierung und Querregelungs-Algorithmen wie LDW, LKA, ALC).</li>\n<li>Das Diagramm harmonisiert die Eingangsgrößen von Sensor-SWCs (Kamera, Lidar, Fusion) für regelnde SWCs (Trajectory Planning, Lateral Control).</li>\n</ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><strong>Referenzsysteme & Entitäten:</strong></li>\n<li><strong>Ego-Fahrzeug (Vehicle-fixed Coordinate System):</strong> Ursprung im Fahrzeugreferenzpunkt (typischerweise Mitte Hinterachse oder vordere Stoßstange je nach Sensorik). Längsachse (Dotted Line / x-Achse) weist in Fahrtrichtung.</li>\n<li><strong>Spurmarkierungen & Leitlinien:</strong></li>\n<li><code>Left edge of the lane</code>: Linke Spurberandung.</li>\n<li><code>Centre of the lane</code>: Spurmittellinie (Trajektorien-Sollachse).</li>\n<li><code>Right edge of the lane</code>: Rechte Spurberandung.</li>\n<li><strong>Definierte Schnittstellenvariablen & Datenstrukturen:</strong></li>\n<li><strong>Offset (Lateraler Versatz $y$):</strong></li>\n<li><em>Definition:</em> Abstand zwischen Fahrzeugreferenzlinie und Fahrspurgrenze bzw. Spurmitte entlang der Querachse.</li>\n<li><em>Vorzeichenkonvention:</em> Positiv nach <strong>links</strong> ($+y$), in Übereinstimmung mit dem fahrzeugfesten ISO-8855-Rechtssystem ($x$ = vorwärts, $y$ = links, $z$ = aufwärts).</li>\n<li><strong>Yaw angle (Gierwinkel / Differenzwinkel $\\Delta\\psi$):</strong></li>\n<li><em>Definition:</em> Winkelversatz zwischen der Fahrzeuglängsachse und der Tangente an die Fahrspur.</li>\n<li><em>Vorzeichenkonvention:</em> Positiv gegen den Uhrzeigersinn (mathematisch positiv / Linksdrehung, $+z$-Achse).</li>\n<li><strong>Road curvature (Straßenkrümmung $\\kappa$ bzw. $c_0$):</strong></li>\n<li><em>Definition:</em> Krümmung der Fahrspur ($\\kappa = \\frac{1}{R}$).</li>\n<li><em>Vorzeichenkonvention:</em> Positiv bei Linkskurven ($+$ nach links gekrümmt), negativ bei Rechtskurven. Typischerweise Bestandteil einer Polynombeschreibung (z. B. $y(x) = c_0 + c_1 x + \\frac{c_2}{2} x^2 + \\frac{c_3}{6} x^3$).</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ul class=\"fig-list\">\n<li><strong>Berechnungszyklus & Datenfluss:</strong></li>\n<li>Sensor-SWCs (z. B. Frontkamera) ermitteln kontinuierlich im Abtasttakt (z. B. 20 ms–50 ms) die Polynom- oder Spline-Koeffizienten sowie die Relativvariablen (<code>Offset</code>, <code>Yaw angle</code>, <code>Road curvature</code>).</li>\n<li>Übertragung via Sender-Receiver-Kommunikation (<code>VariableDataPrototype</code> über <code>Rte_Read</code> / <code>Rte_Write</code> bzw. Non-blocking Data Semantics) an Umfeldmodell- und Fusions-SWCs.</li>\n<li>Nachgelagerte Regler-SWCs (z. B. Lane Keeping Assist) nutzen die Signale zur Bildung der Soll-Gierrate und des Soll-Lenkmoments für unterlagerte VMC-Aktuatoren (EPS - Electric Power Steering).</li>\n<li><strong>Asynchronität / Validierung:</strong></li>\n<li>Statussignale (Confidence Level, Tracking-Status) sichern die geometrischen Variablen ab; bei Verlust der Sichtbarkeit erfolgt Signal-Degradation oder Fallback auf Odometrie.</li>\n</ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li><strong>Vorzeichenkonsistenz (Right-Hand Rule):</strong></li>\n<li>Entwickler von Treiberbausteinen und Sensor-Interfaces müssen sicherstellen, dass Rohdaten proprietärer Sensoren (z. B. Kamerasysteme, die nach rechts positive Vorzeichen liefern) am SWC-Eingangsport exakt auf die AUTOSAR-Vorgabe (links = positiv für Offset, Gierwinkel und Krümmung) invertiert werden.</li>\n<li><strong>Datentypen & Skalierung:</strong></li>\n<li>Verwendung AUTOSAR-konformer <code>ApplicationDataType</code> / <code>ImplementationDataType</code> (z. B. <code>float32</code> oder Festkomma mit <code>CompuMethod</code> für physikalische Einheiten: $\\text{m}$ für Offset, $\\text{rad}$ für Yaw angle, $\\text{1/m}$ für Curvature).</li>\n<li><strong>RTE-Integration:</strong></li>\n<li>Schnittstellenkompatibilität erfordert identische Semantik an P-Port und R-Port (<code>SenderReceiverInterface</code>); Vorzeichenfehler führen unmittelbar zu instabilen Regelkreisen (Mitkopplung statt Gegenkopplung in Querregelalgorithmen).</li>\n</ul>"}], "trans": [{"from": "FIG-51a8048023eaf74b", "to": "FIG-f603d60f8a769973", "fr": "R24-11", "tr": "R25-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
